import{_ as s,c as n,o as e,ag as p}from"./chunks/framework.BeChtK_P.js";const v=JSON.parse('{"title":"PVE 硬盘休眠","description":"","frontmatter":{"title":"PVE 硬盘休眠","author":"welpher.yu","date":"2025-03-18T15:47:11.000Z","tags":["Nas","PVE"],"categories":["居家折腾","服务器"]},"headers":[],"relativePath":"posts/2025/proxmox-ve-hdd-spin-down.md","filePath":"posts/2025/proxmox-ve-hdd-spin-down.md"}'),t={name:"posts/2025/proxmox-ve-hdd-spin-down.md"};function i(l,a,d,o,c,h){return e(),n("div",null,[...a[0]||(a[0]=[p(`<p>OMV用了也有几年了，最近发现OMV当前版本系统已经停止更新，想升级，发现跨两个版本，实在是麻烦。我从最早的gen8用的esxi,用linux玩NAS,转All In One用OMV，也算是折腾了很多次了，OMV这种升级要动太多的系统，想了想还是用虚拟化吧，PVE就这么折腾了起来。</p><p>安装PVE就不详细写了，网上已经有很多教程了。这里就记录一下一点小技巧。PVE 硬盘不休眠的原因基本都是由于pvestatd一直在读取硬盘信息，导致不会休眠。</p><h2 id="不监控硬盘" tabindex="-1">不监控硬盘 <a class="header-anchor" href="#不监控硬盘" aria-label="Permalink to &quot;不监控硬盘&quot;">​</a></h2><h4 id="关闭pvestatd" tabindex="-1">关闭pvestatd <a class="header-anchor" href="#关闭pvestatd" aria-label="Permalink to &quot;关闭pvestatd&quot;">​</a></h4><p>网上有的说是直接把pvestatd关掉，但是关掉后，PVE的监控就全挂了。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pvestatd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span></span></code></pre></div><h4 id="开启-lvm-的-metadata-的缓存" tabindex="-1">开启 lvm 的 metadata 的缓存 <a class="header-anchor" href="#开启-lvm-的-metadata-的缓存" aria-label="Permalink to &quot;开启 lvm 的 metadata 的缓存&quot;">​</a></h4><p>修改/etc/lvm/lvm.conf文件，开启 lvm 的 metadata 的缓存，开启的话，就会缓存 lvm 的信息，就不需要再读取硬盘获取了。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># use_lvmetad=1</span></span>
<span class="line"><span># 开启</span></span>
<span class="line"><span>sed -i &#39;s/use_lvmetad = 0/use_lvmetad = 1/g&#39; /etc/lvm/lvm.conf</span></span>
<span class="line"><span># 重启</span></span>
<span class="line"><span>pvestatd restart</span></span></code></pre></div><p>我看这个文件里没有这个值，也不知道是不是已经过时了。</p><h4 id="过滤不需要监控的盘" tabindex="-1">过滤不需要监控的盘 <a class="header-anchor" href="#过滤不需要监控的盘" aria-label="Permalink to &quot;过滤不需要监控的盘&quot;">​</a></h4><p>首先要找到我们需要监控的盘，建议直接在/dev/disk/by-id/目录下查看。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -l</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/disk/by-id/</span></span></code></pre></div><p>一般来说你的机械硬盘肯定是以ata-开头的。 在 /etc/lvm/lvm.conf 文件里找到 devices 节点，然后添加global_filter，然后重启 lvm 服务。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 添加 &quot;r|/dev/sd*|&quot; 到 global_filter</span></span>
<span class="line"><span>global_filter = [ &quot;r|/dev/zd.*|&quot;, &quot;r|/dev/mapper/pve-.*|&quot;, &quot;r|//dev/disk/by-uuid/ata-WDC.*|&quot; ]</span></span>
<span class="line"><span># 重启</span></span>
<span class="line"><span>pvestatd restart</span></span></code></pre></div><h3 id="设置硬盘休眠" tabindex="-1">设置硬盘休眠 <a class="header-anchor" href="#设置硬盘休眠" aria-label="Permalink to &quot;设置硬盘休眠&quot;">​</a></h3><p>在/etc/hdparam.conf中设置</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 设置 APM(Advanced Power Management) 参数</span></span>
<span class="line"><span># 1-127允许磁盘休眠，128-254不允许，255会完全关闭电源管理功能</span></span>
<span class="line"><span># 但是太激进（数值太小）也可能会容易使硬盘损坏</span></span>
<span class="line"><span># spindown_time = 20 表示硬盘在 20 个 5 秒间隔后休眠。</span></span>
<span class="line"><span> /dev/disk/by-id/ata-ST1000LM035 {</span></span>
<span class="line"><span>         apm = 127</span></span>
<span class="line"><span>         acoustic_management = 127</span></span>
<span class="line"><span>         spindown_time = 20</span></span>
<span class="line"><span> }</span></span>
<span class="line"><span>  /dev/disk/by-id/ata-ST2000DM006 {</span></span>
<span class="line"><span>         apm = 127</span></span>
<span class="line"><span>         acoustic_management = 127</span></span>
<span class="line"><span>         spindown_time = 45</span></span>
<span class="line"><span> }</span></span></code></pre></div>`,18)])])}const m=s(t,[["render",i]]);export{v as __pageData,m as default};
